CREATE TABLE import_batches(id INTEGER PRIMARY KEY, category TEXT NOT NULL, template_version TEXT NOT NULL, source_department TEXT NOT NULL, filename TEXT NOT NULL, file_hash TEXT NOT NULL, original_file BLOB NOT NULL, uploaded_by INTEGER NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL, confirmed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE import_rows(id INTEGER PRIMARY KEY, batch_id INTEGER NOT NULL REFERENCES import_batches(id), sheet TEXT NOT NULL, row_number INTEGER NOT NULL, raw_json TEXT NOT NULL, normalized_json TEXT NOT NULL, state TEXT NOT NULL, error TEXT NOT NULL DEFAULT '', student_id INTEGER, UNIQUE(batch_id,row_number));
CREATE TABLE students(id INTEGER PRIMARY KEY, research_id TEXT NOT NULL UNIQUE, student_number TEXT NOT NULL UNIQUE, name TEXT NOT NULL, college TEXT NOT NULL, major TEXT NOT NULL, level TEXT NOT NULL, entry_year INTEGER NOT NULL, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE student_revisions(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id), version INTEGER NOT NULL, payload TEXT NOT NULL, source_row_id INTEGER NOT NULL REFERENCES import_rows(id), created_at INTEGER NOT NULL, actor_id INTEGER NOT NULL REFERENCES users(id), UNIQUE(student_id,version));
CREATE INDEX import_row_batch ON import_rows(batch_id);
